import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { Button } from "@/registry/erbium/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

const TooltipDemo = () => (
  <Tooltip>
    <TooltipTrigger render={<Button variant="outline">Hover</Button>} />
    <TooltipContent>
      <p>Add to library</p>
    </TooltipContent>
  </Tooltip>
);

export default TooltipDemo;

import { Button } from "@/registry/erbium/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export const TooltipDisabled = () => (
  <>
    <Tooltip>
      <TooltipTrigger render={<span className="inline-block w-fit" />}>
        <Button variant="outline" disabled>
          Disabled
        </Button>
      </TooltipTrigger>
      <TooltipContent>
        <p>This feature is currently unavailable</p>
      </TooltipContent>
    </Tooltip>
  </>
);

import { Icon } from "@/registry/erbium/ui/icon";

import { Button } from "@/registry/erbium/ui/button";
import { Kbd } from "@/registry/erbium/ui/kbd";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export const TooltipKeyboard = () => (
  <Tooltip>
    <TooltipTrigger render={<Button variant="outline" size="icon-sm" />}>
      <Icon name="save" />
    </TooltipTrigger>
    <TooltipContent>
      Save Changes <Kbd hotkey="S" />
    </TooltipContent>
  </Tooltip>
);

import { Button } from "@/registry/erbium/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export const TooltipSides = () => (
  <div className="flex flex-wrap gap-related">
    {(["left", "top", "bottom", "right"] as const).map((side) => (
      <Tooltip key={side}>
        <TooltipTrigger render={<Button variant="outline" className="w-fit capitalize" />}>
          {side}
        </TooltipTrigger>
        <TooltipContent side={side}>
          <p>Add to library</p>
        </TooltipContent>
      </Tooltip>
    ))}
  </div>
);

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { Tooltip } from "@/registry/erbium/ui/tooltip";

import type { Meta, StoryObj } from "@storybook/react";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Tooltip, TooltipTrigger, TooltipContent } from \"@/registry/erbium/ui/tooltip\";\nimport { Button } from \"@/registry/erbium/ui/button\";\n\nconst Example = (args: {\n  side: \"top\" | \"right\" | \"bottom\" | \"left\";\n  align: \"start\" | \"center\" | \"end\";\n  sideOffset: number;\n  defaultOpen: boolean;\n}) => (\n  <Tooltip key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>\n    <TooltipTrigger render={<Button variant=\"outline\">Hover for tooltip</Button>} />\n    <TooltipContent side={args.side} align={args.align} sideOffset={args.sideOffset}>\n      Helpful information\n    </TooltipContent>\n  </Tooltip>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/tooltip-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import SideExample from "./variants/side";

const SideSource = "import { TooltipSides } from \"../examples/tooltip-sides\";\n\nconst Example = () => <TooltipSides />;\n\nexport default Example;\n";

import WithKeyboardShortcutExample from "./variants/with-keyboard-shortcut";

const WithKeyboardShortcutSource = "import { TooltipKeyboard } from \"../examples/tooltip-keyboard\";\n\nconst Example = () => <TooltipKeyboard />;\n\nexport default Example;\n";

import DisabledButtonExample from "./variants/disabled-button";

const DisabledButtonSource = "import { TooltipDisabled } from \"../examples/tooltip-disabled\";\n\nconst Example = () => <TooltipDisabled />;\n\nexport default Example;\n";

const meta = {
  component: Tooltip,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nShow a popup related to an element when it receives keyboard focus or pointer hover.\n\n**Import:** `@/registry/erbium/ui/tooltip`\n\n## Usage\n\n```tsx\nimport {\n  Tooltip,\n  TooltipContent,\n  TooltipTrigger,\n} from \"@/registry/erbium/ui/tooltip\"\nimport {{ Button }} from \"@/registry/erbium/ui/button\"\n```\n\n```tsx\n<Tooltip>\n  <TooltipTrigger render={<Button variant=\"outline\">Hover</Button>} />\n  <TooltipContent>\n    <p>Add to library</p>\n  </TooltipContent>\n</Tooltip>\n```\n\n## Composition\n\nUse the following composition to build a `Tooltip`:\n\n```text\nTooltip\n├── TooltipTrigger\n└── TooltipContent\n```\n\n## Interaction ownership\n\nKeep tooltip content tied to hover or focus on its current trigger. Remounting a closed trigger should not animate the tooltip open. Tooltips do not take focus; keep actions and interactive content in a Popover instead.\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Tooltip](https://base-ui.com/react/components/tooltip)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Tooltip>;

export default { ...meta, title: "Components/Tooltip",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  side: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
  sideOffset: number;
  defaultOpen: boolean;
}> = {
  argTypes: {
    align: { control: "select", options: ["start", "center", "end"] },
    defaultOpen: { control: "boolean" },
    side: { control: "select", options: ["top", "right", "bottom", "left"] },
    sideOffset: { control: "number" },
  },
  args: { align: "center", defaultOpen: false, side: "top", sideOffset: 4 },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Side: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `side` prop to change the position of the tooltip." },
      source: { code: SideSource },
    },
  },
  render: SideExample,
};

export const WithKeyboardShortcut: Story = {
  parameters: {
    docs: {
      description: { story: "Show a keyboard shortcut in tooltip content." },
      source: { code: WithKeyboardShortcutSource },
    },
  },
  render: WithKeyboardShortcutExample,
};

export const DisabledButton: Story = {
  parameters: {
    docs: {
      description: { story: "Show a tooltip on a disabled button by wrapping it with a span." },
      source: { code: DisabledButtonSource },
    },
  },
  render: DisabledButtonExample,
};

import { TooltipDisabled } from "../examples/tooltip-disabled";

const Example = () => <TooltipDisabled />;

export default Example;

import Demo from "../examples/tooltip-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

import { Tooltip, TooltipTrigger, TooltipContent } from "@/registry/erbium/ui/tooltip";
import { Button } from "@/registry/erbium/ui/button";

const Example = (args: {
  side: "top" | "right" | "bottom" | "left";
  align: "start" | "center" | "end";
  sideOffset: number;
  defaultOpen: boolean;
}) => (
  <Tooltip key={String(args.defaultOpen)} defaultOpen={args.defaultOpen}>
    <TooltipTrigger render={<Button variant="outline">Hover for tooltip</Button>} />
    <TooltipContent side={args.side} align={args.align} sideOffset={args.sideOffset}>
      Helpful information
    </TooltipContent>
  </Tooltip>
);

export default Example;

import { TooltipSides } from "../examples/tooltip-sides";

const Example = () => <TooltipSides />;

export default Example;

import { TooltipKeyboard } from "../examples/tooltip-keyboard";

const Example = () => <TooltipKeyboard />;

export default Example;
